import{o as i,c as r,a0 as s,j as e,t,p as l}from"./chunks/framework.L_oL6aia.js";const d={class:"rock-copy-email-wrapper inline"},g=JSON.parse('{"title":"Midnight Rambler: Manual de Usuario","description":"","frontmatter":{},"headers":[],"relativePath":"es/midnight-rambler.md","filePath":"es/midnight-rambler.md"}'),c={name:"es/midnight-rambler.md"},b=Object.assign(c,{setup(u){const o=l("Copiar Correo");function n(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),o.value="¡Copiado!",setTimeout(function(){o.value="Copiar Correo"},2e3)}return(p,a)=>(i(),r("div",null,[a[1]||(a[1]=s(`<h1 id="midnight-rambler-manual-de-usuario" tabindex="-1">Midnight Rambler: Manual de Usuario <a class="header-anchor" href="#midnight-rambler-manual-de-usuario" aria-label="Permalink to &quot;Midnight Rambler: Manual de Usuario&quot;">​</a></h1><p><strong>Stompbox Series #01 · Simulación de Amplificador Neural</strong></p><div class="print-hide"><img src="/logo.jpg" alt="Midnight Rambler Label" style="max-height:280px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:4px;"></div><h2 id="_1-introduccion" tabindex="-1">1. Introducción <a class="header-anchor" href="#_1-introduccion" aria-label="Permalink to &quot;1. Introducción&quot;">​</a></h2><p>Midnight Rambler es un simulador de amplificador de guitarra en formato de pedal, diseñado para ofrecer los tonos sagrados, crudos y sensibles al tacto del legendario amplificador de guitarra <strong>Fender Tweed Deluxe 5E3</strong> de la década de 1950.</p><p>A diferencia de los plugins de simulación convencionales con decenas de perillas y opciones de enrutamiento infinitas, Midnight Rambler condensa el espíritu del hardware clásico en una interfaz ágil de 4 perillas, permitiendo que tu tono de guitarra atraviese instantáneamente una mezcla estéreo sin fatiga por exceso de opciones. Está construido sobre el ecosistema <strong>Neural Amp Modeler (NAM)</strong> de código abierto y convolution IR personalizada, entregando calidez y saturación valvular auténticas sin aliasing digital con un consumo de CPU ultra bajo.</p><hr><h2 id="_2-flujo-de-senal-y-controles" tabindex="-1">2. Flujo de Señal y Controles <a class="header-anchor" href="#_2-flujo-de-senal-y-controles" aria-label="Permalink to &quot;2. Flujo de Señal y Controles&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ ENTRADA GUITARRA ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ CONTROL DE GANANCIA Y FILTRO HPF ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ MOTOR NEURAL 5E3 TWEED DE 2 CANALES ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ CONTROL DE TONO POST-AMPLIFICADOR Y SALIDA MAESTRA ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ CONVOLUCIÓN DE IMPULSO DE GABINETE ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ SALIDA ESTÉREO (MIX READY) ]</span></span></code></pre></div><h3 id="_1-gain-ganancia-de-entrada-saturacion" tabindex="-1">1. GAIN (Ganancia de Entrada / Saturación) <a class="header-anchor" href="#_1-gain-ganancia-de-entrada-saturacion" aria-label="Permalink to &quot;1. GAIN (Ganancia de Entrada / Saturación)&quot;">​</a></h3><ul><li><strong>Función:</strong> Controla el nivel de la señal de entrada antes de entrar a la etapa del amplificador neural.</li><li><strong>Rango:</strong> Escala analógica de <code>1.0</code> a <code>10.0</code> (Predeterminado: <code>7.0</code> = <code>0.0 dB</code> Ganancia Unitaria, Max: <code>10.0</code> = <code>+6.0 dB</code>).</li><li><strong>Respuesta de Hardware (Curva Lineal Pura):</strong><ul><li>Cada paso ajusta la señal linealmente en incrementos exactos de <code>+2.0 dB</code>.</li><li><strong><code>1.0</code> (-12.0 dB):</strong> Útil para limpiar el canal Cranked y obtener armónicos sutiles en los bordes de la ruptura.</li><li><strong><code>7.0</code> (0.0 dB):</strong> Ganancia unitaria y balance nominal de señal pura.</li><li><strong><code>10.0</code> (+6.0 dB):</strong> Nivel de boost analógico masivo, empujando los modelos neuronales hacia un territorio pesado similar al fuzz.</li></ul></li></ul><h3 id="_2-hpf-filtro-pasa-altos-analogico" tabindex="-1">2. HPF (Filtro Pasa Altos Analógico) <a class="header-anchor" href="#_2-hpf-filtro-pasa-altos-analogico" aria-label="Permalink to &quot;2. HPF (Filtro Pasa Altos Analógico)&quot;">​</a></h3><ul><li><strong>Función:</strong> Un filtro Pasa Altos de primer orden (First Order High-Pass Filter) ubicado <em>antes</em> de la etapa del amplificador neural, afinado para domar las pastillas humbucker en amplificadores que de otra manera tendrían graves sucios y desenfocados.</li><li><strong>Rango:</strong> Frecuencia de corte de barrido continuo desde <code>20 Hz</code> hasta <code>160 Hz</code> (-3 dB por octava).</li><li><strong>Uso:</strong> Recorta el ruido subgrave innecesario para mantener las pistas rítmicas ajustadas y contundentes. A 20 Hz el filtro está completamente abierto.</li></ul><h3 id="_3-tone-corte-de-tono-filtro-lp" tabindex="-1">3. TONE (Corte de Tono - Filtro LP) <a class="header-anchor" href="#_3-tone-corte-de-tono-filtro-lp" aria-label="Permalink to &quot;3. TONE (Corte de Tono - Filtro LP)&quot;">​</a></h3><ul><li><strong>Función:</strong> Un Filtro Pasa Bajos de topología State-Variable TPT ubicado después del amplificador, diseñado para controlar la presencia en frecuencias altas.</li><li><strong>Rango:</strong> <code>1.0 kHz</code> a <code>20.0 kHz</code>.</li><li><strong>Uso:</strong> Domestica el &quot;fizz&quot; digital y las frecuencias altas ásperas. Los valores más altos brindan una claridad cristalina, mientras que reducirlo proporciona un carácter vintage cálido, amaderado y rico en medios.</li></ul><h3 id="_4-master-volumen-maestro" tabindex="-1">4. MASTER (Volumen Maestro) <a class="header-anchor" href="#_4-master-volumen-maestro" aria-label="Permalink to &quot;4. MASTER (Volumen Maestro)&quot;">​</a></h3><ul><li><strong>Función:</strong> Control de nivel de salida lineal y limpio.</li><li><strong>Rango:</strong> Escala analógica de <code>1.0</code> a <code>10.0</code> (Predeterminado: <code>7.0</code> = <code>0.0 dB</code> Ganancia Unitaria, Max: <code>10.0</code> = <code>+18.0 dB</code>).</li><li><strong>Respuesta (Curva Continua de Amplificador Real):</strong><ul><li>Cada paso aumenta el nivel en un uniforme <code>+6.0 dB</code>.</li><li><strong><code>1.0</code> (-36.0 dB):</strong> Nivel suave de práctica de dormitorio, audible de inmediato sin zonas muertas.</li><li><strong><code>7.0</code> (0.0 dB):</strong> Ganancia unitaria nominal estándar.</li><li><strong><code>10.0</code> (+18.0 dB):</strong> Aumento de volumen limpio masivo para pastillas single-coil vintage de baja salida o para empujar efectos en cadena.</li></ul></li></ul><h3 id="_5-channel-selector-de-modo-dual-de-amplificador" tabindex="-1">5. CHANNEL (Selector de Modo Dual de Amplificador) <a class="header-anchor" href="#_5-channel-selector-de-modo-dual-de-amplificador" aria-label="Permalink to &quot;5. CHANNEL (Selector de Modo Dual de Amplificador)&quot;">​</a></h3><p>Alterna entre dos capturas neuronales boutique de alta resolución distintas:</p><ol><li><strong>EDGE (Ruptura):</strong> Captura en el umbral de la ruptura de bulbos (edge-of-breakup) con respuesta táctil hiperdinámica. Responde instantáneamente a los ajustes del potenciómetro de volumen de la guitarra y a la intensidad de la púa. Incluye una compensación de nivel de salida interna de +2.0 dB para igualar la sonoridad percibida con el modo Cranked.</li><li><strong>CRANKED (Rock &#39;N&#39; Roll):</strong> Saturación Tweed al máximo volumen con compresión densa de bulbos de potencia, armónicos cremosos y un sostenido cantante.</li></ol><h3 id="_6-mic-cab-convolucion-de-impulso-de-gabinete" tabindex="-1">6. MIC / CAB (Convolución de Impulso de Gabinete) <a class="header-anchor" href="#_6-mic-cab-convolucion-de-impulso-de-gabinete" aria-label="Permalink to &quot;6. MIC / CAB (Convolución de Impulso de Gabinete)&quot;">​</a></h3><p>Alterna entre tres respuestas curadas de gabinetes de altavoces usando convolución en tiempo real sin latencia:</p><ol><li><strong>WARM (Micrófono de Cinta Royer R121):</strong> Tono grueso y con mucho cuerpo con agudos suaves y medios graves ricos, ideal para ritmos grasientos y slide guitar.</li><li><strong>SHARP (Dinámico Shure SM57):</strong> Mordida de rock clásico con un golpe enfocado en los medios agudos que corta sin esfuerzo en mezclas densas.</li><li><strong>BLEND (Mezcla Personalizada 60/40):</strong> La combinación de estudio definitiva (60% SM57 + 40% R121) que ofrece mordida equilibrada, profundidad y realismo tridimensional.</li></ol><h3 id="_7-standby-interruptor-de-silencio-0-cpu" tabindex="-1">7. STANDBY (Interruptor de Silencio / 0% CPU) <a class="header-anchor" href="#_7-standby-interruptor-de-silencio-0-cpu" aria-label="Permalink to &quot;7. STANDBY (Interruptor de Silencio / 0% CPU)&quot;">​</a></h3><ul><li><strong>Función:</strong> Replica un interruptor de standby de un amplificador físico, silenciando completamente la ruta de audio y reduciendo el consumo de CPU al <strong>0%</strong> de inmediato.</li></ul><h3 id="_8-skin-de-fondo-dinamico-arrastrar-y-soltar" tabindex="-1">8. Skin de Fondo Dinámico (Arrastrar y Soltar) <a class="header-anchor" href="#_8-skin-de-fondo-dinamico-arrastrar-y-soltar" aria-label="Permalink to &quot;8. Skin de Fondo Dinámico (Arrastrar y Soltar)&quot;">​</a></h3><ul><li>Puedes arrastrar y soltar cualquier archivo de imagen (<code>.jpg</code>, <code>.jpeg</code> o <code>.png</code>) directamente desde tu explorador de archivos hacia la interfaz del plugin para personalizar su apariencia visual en tiempo real.</li></ul><hr><h2 id="_3-configuracion-de-audio-standalone" tabindex="-1">3. Configuración de Audio (Standalone) <a class="header-anchor" href="#_3-configuracion-de-audio-standalone" aria-label="Permalink to &quot;3. Configuración de Audio (Standalone)&quot;">​</a></h2><p>Cuando ejecutes el pedal como una aplicación independiente, configura tus ajustes de audio de la siguiente manera para un rendimiento óptimo:</p><ol><li><strong>Tipo de Dispositivo de Audio:</strong> Selecciona siempre <strong>ASIO</strong> en Windows para evitar latencia y distorsión digital.</li><li><strong>Dispositivo:</strong> Selecciona el controlador ASIO nativo de tu interfaz de audio (ej., <em>Focusrite USB ASIO</em>).</li><li><strong>Frecuencia de Muestreo (Sample Rate):</strong> Ajústalo a <strong>48000 Hz</strong> (48 kHz).</li><li><strong>Tamaño de Búfer (Buffer Size):</strong> Ajusta el tamaño del búfer a <strong>128 muestras</strong> (2.3 ms) o <strong>256 muestras</strong> (5.3 ms).</li></ol><h4 id="🎸-el-fenomeno-del-bufer-por-que-256-muestras-5-3-ms-podria-sonar-mejor-que-128-muestras-2-3-ms" tabindex="-1">🎸 El Fenómeno del Búfer: Por qué 256 muestras (5.3 ms) podría sonar mejor que 128 muestras (2.3 ms) <a class="header-anchor" href="#🎸-el-fenomeno-del-bufer-por-que-256-muestras-5-3-ms-podria-sonar-mejor-que-128-muestras-2-3-ms" aria-label="Permalink to &quot;🎸 El Fenómeno del Búfer: Por qué 256 muestras (5.3 ms) podría sonar mejor que 128 muestras (2.3 ms)&quot;">​</a></h4><p>Muchos guitarristas experimentan un tono más dulce y fluido a 256 muestras. Esto se debe a dos factores:</p><ul><li><strong>Estabilidad del Procesador:</strong> A 256 muestras, la CPU procesa bloques de audio con más margen, evitando micro fluctuaciones (jitters) que pueden introducir aspereza sutil en los agudos.</li><li><strong>Efecto de Duplicación Acústica:</strong> El diminuto retardo de 5.3 ms, combinado con el sonido acústico físico de tus cuerdas eléctricas desenchufadas vibrando en la habitación, crea un efecto orgánico de duplicación (doubling) que agrega profundidad tridimensional, grosor y una sensación natural de reverberación de sala a tu interpretación.</li></ul><hr><h2 id="_4-requisitos-del-sistema-y-distribucion" tabindex="-1">4. Requisitos del Sistema y Distribución <a class="header-anchor" href="#_4-requisitos-del-sistema-y-distribucion" aria-label="Permalink to &quot;4. Requisitos del Sistema y Distribución&quot;">​</a></h2><h3 id="requisitos-del-sistema" tabindex="-1">Requisitos del Sistema <a class="header-anchor" href="#requisitos-del-sistema" aria-label="Permalink to &quot;Requisitos del Sistema&quot;">​</a></h3><ul><li><strong>Sistemas Operativos</strong>: <ul><li><strong>Windows</strong>: Windows 10 o Windows 11 (64-bit).</li><li><strong>macOS</strong>: macOS 10.13 o más reciente (soporta de forma nativa Intel y Apple Silicon).</li><li><strong>Linux</strong>: Ubuntu 22.04 o distribución de 64-bit compatible.</li></ul></li><li><strong>Procesador (CPU)</strong>: Debe soportar instrucciones <strong>AVX2</strong> (Intel Core 4ª Generación / AMD Ryzen o más recientes) en Windows y Linux para calcular los modelos matemáticos en tiempo real. Los procesadores Apple Silicon son compatibles de forma nativa.</li><li><strong>RAM</strong>: 4 GB mínimo.</li><li><strong>Tarjeta de Audio (Modo Standalone)</strong>: Interfaz de audio con controladores de baja latencia (<strong>ASIO</strong> nativo en Windows; <strong>CoreAudio</strong> en macOS; <strong>JACK</strong> o <strong>ALSA</strong> en Linux).</li></ul><h3 id="distribucion-todo-en-uno" tabindex="-1">Distribución (Todo en Uno) <a class="header-anchor" href="#distribucion-todo-en-uno" aria-label="Permalink to &quot;Distribución (Todo en Uno)&quot;">​</a></h3><p><strong>Midnight Rambler es 100% autónomo.</strong> No requiere cargar modelos externos, configuraciones XML ni archivos IR por separado:</p><ul><li>Todos los modelos de amplificadores neuronales y perfiles de gabinetes están <strong>incrustados internamente como recursos binarios</strong> dentro del archivo del plugin.</li><li><strong>Windows</strong>: Simplemente copia el archivo <code>.vst3</code> en tu carpeta de plugins (usualmente <code>C:\\Program Files\\Common Files\\VST3\\</code>) o ejecuta la aplicación <code>.exe</code> (Standalone).</li><li><strong>macOS</strong>: Copia el <code>.vst3</code> o <code>.component</code> (AU) en tu carpeta de plugins (usualmente <code>/Library/Audio/Plug-Ins/VST3/</code> o <code>/Library/Audio/Plug-Ins/Components/</code>) o ejecuta la app <code>.app</code> (Standalone).</li><li><strong>Linux</strong>: Copia el archivo <code>.vst3</code> en tu carpeta de plugins (usualmente <code>~/.vst3/</code> o <code>/usr/lib/vst3/</code>) o ejecuta el binario independiente.</li></ul><hr><h2 id="_5-solucion-de-problemas-troubleshooting" tabindex="-1">5. Solución de Problemas (Troubleshooting) <a class="header-anchor" href="#_5-solucion-de-problemas-troubleshooting" aria-label="Permalink to &quot;5. Solución de Problemas (Troubleshooting)&quot;">​</a></h2><h3 id="el-vst3-no-aparece-en-el-daw-o-falla-al-escanear" tabindex="-1">El VST3 no aparece en el DAW o falla al escanear <a class="header-anchor" href="#el-vst3-no-aparece-en-el-daw-o-falla-al-escanear" aria-label="Permalink to &quot;El VST3 no aparece en el DAW o falla al escanear&quot;">​</a></h3><ul><li><strong>Falta C++ Redistributable (Windows)</strong>: Aunque el plugin está compilado estáticamente, algunas instalaciones de Windows pueden carecer de componentes de ejecución básicos. Descarga e instala el <a href="https://aka.ms/vs/17/release/vc_redist.x64.exe" target="_blank" rel="noreferrer">Microsoft Visual C++ Redistributable 2015-2022 (x64)</a> oficial.</li><li><strong>Compatibilidad de CPU (AVX2)</strong>: Asegúrate de que tu procesador soporte instrucciones <strong>AVX2</strong>. El motor neuronal subyacente NAM requiere AVX2 para calcular las redes neuronales en tiempo real en Windows y Linux. Si tu CPU carece de AVX2, el plugin no cargará.</li><li><strong>Ruta de Escaneo</strong>: Verifica que tu DAW esté escaneando la carpeta donde colocaste el archivo <code>.vst3</code>.</li></ul><h3 id="la-aplicacion-standalone-muestra-una-advertencia-de-desarrollador-no-identificado-macos" tabindex="-1">La aplicación Standalone muestra una advertencia de &quot;Desarrollador no identificado&quot; (macOS) <a class="header-anchor" href="#la-aplicacion-standalone-muestra-una-advertencia-de-desarrollador-no-identificado-macos" aria-label="Permalink to &quot;La aplicación Standalone muestra una advertencia de &quot;Desarrollador no identificado&quot; (macOS)&quot;">​</a></h3><ul><li><strong>Explicación</strong>: Debido a que los binarios del plugin se compilan mediante integración continua (CI) automatizada y no están notarizados con una Cuenta de Desarrollador de Apple paga, macOS puede evitar que se inicien.</li><li><strong>Solución</strong>: Ve a <strong>Configuración del Sistema &gt; Privacidad y Seguridad</strong>, desplázate hacia abajo hasta la sección de Seguridad y haz clic en <strong>Abrir de todos modos</strong> junto a la advertencia de Midnight Rambler. Como alternativa, abre Terminal y ejecuta: <code>xattr -cr /ruta/hacia/MidnightRambler.app</code></li></ul><h3 id="chasquidos-pops-o-alta-latencia-en-modo-standalone" tabindex="-1">Chasquidos, pops o alta latencia en modo Standalone <a class="header-anchor" href="#chasquidos-pops-o-alta-latencia-en-modo-standalone" aria-label="Permalink to &quot;Chasquidos, pops o alta latencia en modo Standalone&quot;">​</a></h3><ul><li><strong>Controladores de Audio (Drivers)</strong>: Asegúrate de estar usando el controlador nativo de baja latencia para tu interfaz de audio (<strong>ASIO</strong> en Windows, <strong>CoreAudio</strong> en macOS, <strong>JACK</strong> o <strong>ALSA</strong> en Linux).</li><li><strong>Tamaño del Búfer</strong>: Se recomienda un tamaño de búfer de <strong>128</strong> o <strong>256 muestras</strong>. Reducirlo a menos de 64 muestras puede causar picos de CPU y crujidos en el audio dependiendo del rendimiento de tu computadora.</li></ul><hr><h3 id="¡queremos-escuchar-tus-mezclas" tabindex="-1">¡Queremos escuchar tus mezclas! <a class="header-anchor" href="#¡queremos-escuchar-tus-mezclas" aria-label="Permalink to &quot;¡Queremos escuchar tus mezclas!&quot;">​</a></h3><p>El comportamiento dinámico de Midnight Rambler se calibró directamente a partir de pruebas de audición de discos clásicos. Si has grabado una canción o mezclado una pista usando este pedal, ¡queremos escucharla!</p><p>Copia nuestro correo electrónico de contacto para compartir tus enlaces o comentarios:</p>`,53)),e("div",d,[a[0]||(a[0]=e("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),e("button",{class:"rock-copy-btn",onClick:n},t(o.value),1)]),a[2]||(a[2]=e("p",{style:{"margin-top":"2rem","margin-bottom":"1rem"}},"Si deseas apoyar nuestra investigación independiente y ayudarnos a mantener nuestros plugins gratuitos, puedes apoyarnos con Tarjeta, PayPal o Criptomonedas:",-1)),a[3]||(a[3]=e("div",null,[e("a",{href:"/es/support",class:"rock-btn rock-btn-primary",style:{display:"inline-block","text-align":"center"}},"Apoya el Laboratorio (Ko-fi / Crypto) ☕")],-1))]))}});export{g as __pageData,b as default};
